import type { VideoProvider } from "@/lib/types";

/**
 * Video embed provider layer.
 *
 * Security rules enforced here (and mirrored by unit tests):
 *  - Admin never supplies raw HTML. Only a URL is accepted.
 *  - The URL is parsed with the WHATWG URL parser; the hostname is compared
 *    for EXACT equality against an allowlist. Substring/`includes` checks are
 *    never used, so `youtube.com.evil.test` or `notyoutube.com` are rejected.
 *  - Only `https:` is accepted. `javascript:`, `data:`, `http:` and any other
 *    scheme are rejected.
 *  - Embed URLs are always generated by us from validated identifiers; we
 *    never echo admin-supplied markup back into an iframe `src`.
 *  - We never fetch, proxy, download or scrape the supplied URL.
 */

export interface ParsedVideo {
  provider: VideoProvider;
  /** Provider-native identifier, e.g. a YouTube video id. */
  videoId: string;
  /** Canonical, human-openable page URL on the provider. */
  canonicalUrl: string;
}

export type VideoParseResult =
  | { ok: true; video: ParsedVideo }
  | { ok: false; error: string; hint?: string };

const YOUTUBE_HOSTS = new Set([
  "youtube.com",
  "www.youtube.com",
  "m.youtube.com",
  "music.youtube.com",
  "youtu.be",
  "www.youtu.be",
  "youtube-nocookie.com",
  "www.youtube-nocookie.com",
]);

const FACEBOOK_HOSTS = new Set([
  "facebook.com",
  "www.facebook.com",
  "web.facebook.com",
  "m.facebook.com",
  "fb.watch",
  "fb.com",
  "www.fb.com",
]);

/** YouTube video ids are exactly 11 chars of the URL-safe base64 alphabet. */
const YOUTUBE_ID_RE = /^[A-Za-z0-9_-]{11}$/;

function parseUrl(raw: string): URL | null {
  const trimmed = raw.trim();
  if (!trimmed) return null;
  // Reject control characters and whitespace inside the URL, which the URL
  // parser tolerates by percent-encoding and which are a classic bypass vector.
  if (/[\s\u0000-\u001f\u007f]/.test(trimmed)) return null;
  try {
    return new URL(trimmed);
  } catch {
    return null;
  }
}

function isAllowedHost(host: string, allowlist: Set<string>): boolean {
  const normalized = host.toLowerCase();
  if (allowlist.has(normalized)) return true;
  // youtube-nocookie is a legitimate subdomain used for privacy-enhanced embeds.
  return normalized.endsWith(".youtube-nocookie.com");
}

function extractYouTubeId(url: URL): string | null {
  const host = url.hostname.toLowerCase();

  if (host === "youtu.be" || host === "www.youtu.be") {
    const id = url.pathname.split("/").filter(Boolean)[0] ?? "";
    return YOUTUBE_ID_RE.test(id) ? id : null;
  }

  if (host === "youtube.com" || host === "www.youtube.com" || host === "m.youtube.com" || host === "music.youtube.com") {
    const path = url.pathname;

    // /watch?v=ID
    if (path === "/watch") {
      const v = url.searchParams.get("v");
      if (v && YOUTUBE_ID_RE.test(v)) return v;
      return null;
    }

    // /embed/ID, /v/ID, /live/ID
    const segments = path.split("/").filter(Boolean);
    if (segments.length >= 2) {
      const [kind, id] = segments;
      if ((kind === "embed" || kind === "v" || kind === "live") && id && YOUTUBE_ID_RE.test(id)) {
        return id;
      }
    }

    // /shorts/ID
    if (segments.length === 2 && segments[0] === "shorts") {
      const id = segments[1]!;
      return YOUTUBE_ID_RE.test(id) ? id : null;
    }
  }

  if (host === "youtube-nocookie.com" || host === "www.youtube-nocookie.com") {
    const segments = url.pathname.split("/").filter(Boolean);
    if (segments.length >= 2 && segments[0] === "embed") {
      const id = segments[1]!;
      return YOUTUBE_ID_RE.test(id) ? id : null;
    }
  }

  return null;
}

/**
 * Facebook's official Embedded Video Player is served from `facebook.com/plugins/video.php`.
 * The player needs either a numeric video id or a canonical public watch URL.
 *
 * We deliberately do NOT guess ids for formats we cannot normalise - a wrong
 * guess produces an iframe that silently fails with a cross-origin error we
 * cannot detect. Instead we return an actionable error message.
 */
function extractFacebookId(url: URL): { id: string | null; href: string | null } {
  const path = url.pathname;

  // /plugins/video.php?href=<absolute facebook watch url>
  if (path === "/plugins/video.php") {
    return { id: null, href: url.searchParams.get("href") };
  }

  // /watch/?v=<id>  (numeric id)
  if (path === "/watch/" || path === "/watch") {
    const v = url.searchParams.get("v");
    if (v && /^\d+$/.test(v)) {
      return { id: v, href: null };
    }
    return { id: null, href: null };
  }

  // /reel/<id>, /<page>/videos/<id>, /<page>/videos/<id>/ - the numeric id is
  // always the last path segment for these shapes.
  const segments = path.split("/").filter(Boolean);
  if (segments.length >= 2) {
    const last = segments[segments.length - 1]!;
    if (/^\d+$/.test(last)) {
      return { id: last, href: null };
    }
  }

  // /share/v/<token> style links cannot be normalised to a numeric id and are
  // NOT accepted as permalinks: the official plugin cannot embed them.
  return { id: null, href: null };
}

export function parseVideoUrl(raw: string): VideoParseResult {
  if (typeof raw !== "string" || raw.trim().length === 0) {
    return { ok: false, error: "URL video không được để trống." };
  }

  if (raw.trim().length > 2048) {
    return { ok: false, error: "URL video quá dài (tối đa 2048 ký tự)." };
  }

  const url = parseUrl(raw);
  if (!url) {
    return {
      ok: false,
      error: "URL không hợp lệ.",
      hint: "Hãy dán URL đầy đủ, ví dụ https://www.youtube.com/watch?v=XXXXXXXXXXX",
    };
  }

  if (url.protocol !== "https:") {
    return {
      ok: false,
      error: `Chỉ được phép URL HTTPS (hiện tại: ${url.protocol.replace(":", "")}).`,
      hint: "Các URL http, javascript: hoặc data: đều bị từ chối.",
    };
  }

  const host = url.hostname.toLowerCase();

  // --- YouTube -------------------------------------------------------------
  if (isAllowedHost(host, YOUTUBE_HOSTS)) {
    const id = extractYouTubeId(url);
    if (!id) {
      return {
        ok: false,
        error: "Không tìm thấy video ID trong URL YouTube.",
        hint: "Các định dạng hỗ trợ: youtube.com/watch?v=ID, youtu.be/ID, youtube.com/shorts/ID, youtube.com/embed/ID",
      };
    }
    return {
      ok: true,
      video: {
        provider: "youtube",
        videoId: id,
        canonicalUrl: `https://www.youtube.com/watch?v=${id}`,
      },
    };
  }

  // --- Facebook ------------------------------------------------------------
  if (isAllowedHost(host, FACEBOOK_HOSTS)) {
    const { id } = extractFacebookId(url);

    if (id) {
      return {
        ok: true,
        video: {
          provider: "facebook",
          videoId: id,
          canonicalUrl: `https://www.facebook.com/watch/?v=${id}`,
        },
      };
    }

    // A canonical public watch/reel permalink can still be played by the
    // official plugin via its `href` parameter. Only these two shapes are
    // accepted - a `/share/` link or an opaque token cannot be embedded, and
    // guessing would produce an iframe that fails silently.
    const isFacebookPermalink =
      (host === "facebook.com" ||
        host === "www.facebook.com" ||
        host === "m.facebook.com" ||
        host === "web.facebook.com") &&
      (url.pathname.startsWith("/watch") || url.pathname.startsWith("/reel"));

    if (isFacebookPermalink) {
      // Store the permalink itself as the source; the embed builder will use
      // the official plugin with the `href` parameter.
      return {
        ok: true,
        video: {
          provider: "facebook",
          videoId: url.pathname + url.search,
          canonicalUrl: `https://www.facebook.com${url.pathname}${url.search}`,
        },
      };
    }

    return {
      ok: false,
      error: "Không thể chuẩn hóa URL Facebook này thành video có thể nhúng.",
      hint: "Hãy dùng link dạng https://www.facebook.com/watch/?v=<id> hoặc https://www.facebook.com/plugins/video.php?href=<link>. Video phải ở chế độ công khai để được nhúng.",
    };
  }

  return {
    ok: false,
    error: `Nguồn video không được hỗ trợ (hostname: ${host}).`,
    hint: "Chỉ chấp nhận youtube.com, youtu.be và facebook.com.",
  };
}

/**
 * Builds a safe iframe `src` from a validated source URL.
 * Never returns the raw admin input; the URL is re-parsed and re-validated.
 */
export function buildEmbedUrl(sourceUrl: string): { embedUrl: string; provider: VideoProvider; canonicalUrl: string } | null {
  const parsed = parseVideoUrl(sourceUrl);
  if (!parsed.ok) return null;

  const { provider, videoId, canonicalUrl } = parsed.video;

  if (provider === "youtube") {
    const params = new URLSearchParams({
      rel: "0",
      modestbranding: "1",
      playsinline: "1",
      // No autoplay: we never force playback with sound.
    });
    return {
      provider,
      canonicalUrl,
      embedUrl: `https://www.youtube-nocookie.com/embed/${videoId}?${params.toString()}`,
    };
  }

  // Facebook Embedded Video Player (official plugin endpoint).
  const params = new URLSearchParams({
    href: canonicalUrl,
    show_text: "0",
    autoplay: "0",
  });
  return {
    provider,
    canonicalUrl,
    embedUrl: `https://www.facebook.com/plugins/video.php?${params.toString()}`,
  };
}

export function providerLabel(provider: VideoProvider): string {
  return provider === "youtube" ? "YouTube" : "Facebook";
}

export const PROVIDER_HINTS: Record<VideoProvider, string> = {
  youtube:
    "Hỗ trợ: youtube.com/watch?v=ID, youtu.be/ID, youtube.com/shorts/ID, youtube.com/embed/ID. Video phải công khai hoặc nhúng được.",
  facebook:
    "Hỗ trợ: facebook.com/watch/?v=<id> hoặc facebook.com/plugins/video.php?href=<link>. Video phải công khai và được phép nhúng.",
};
